sn_aia_tool.script:
(function(inputs, _agentic_context_) {
    var TABLE = 'x_birl3_clm_customer_performance';
    var CUST_TABLE = 'x_birl3_clm_clm_customer_master1';
    var REF_FIELD = 'customer_name';            // Reference on Customer Performance
    var CUST_NAME_FIELD = 'customer_name';      // Customer Name on CLM Customer Masters
    var CUST_CODE_FIELD = 'customer_code_sap';  // Customer Code SAP on CLM Customer Masters

    var customerInput = (inputs.customer_name || '').toString().trim();
    if (!customerInput) return fail('customer_name is required');

    try {
        // 1. Resolve the customer
        var cust = resolveCustomer(customerInput);
        if (cust.status !== 'found') return JSON.stringify(cust);

        // 2. Upsert the Customer Performance record (one per customer)
        var perf = new GlideRecord(TABLE);
        perf.addQuery(REF_FIELD, cust.sys_id);
        perf.orderByDesc('sys_updated_on');
        perf.setLimit(1);
        perf.query();

        var isUpdate = perf.next();
        if (!isUpdate) perf.initialize();

        perf.setValue(REF_FIELD, cust.sys_id);
        perf.setValue('company_name', inputs.company_name || cust.name || '');
        perf.setValue('current_stock_price', inputs.current_stock_price || '');
        perf.setValue('market_stock_insight', inputs.company_overview || '');   // Company Overview
        perf.setValue('financial_highlights', inputs.financial_highlights || '');
        perf.setValue('major_developments', inputs.major_developments || '');
        perf.setValue('key_news_highlights', inputs.recent_news || '');         // Recent News
        perf.setValue('final_recommendation', inputs.final_recommendation || '');
        perf.setValue('assessment_status', 'completed');

        var sysId = isUpdate ? perf.update() : perf.insert();
        if (!sysId) return fail('Save failed: ' + perf.getLastErrorMessage());

        return JSON.stringify({
            status: 'success',
            action: isUpdate ? 'updated' : 'created',
            customer: cust.name,
            sys_id: sysId
        });

    } catch (e) {
        gs.error('[CLM VRI] Save failed: ' + (e.message || e));
        return fail(String(e.message || e));
    }

    // ---------- Helpers ----------

    function resolveCustomer(input) {
        var cleaned = input.replace(/\s+/g, ' ').trim();

        // A) sys_id from the widget / trigger
        if (/^[0-9a-f]{32}$/i.test(cleaned)) {
            var name = '';
            var byId = new GlideRecord(CUST_TABLE);
            if (byId.get(cleaned)) name = byId.getValue(CUST_NAME_FIELD);
            return { status: 'found', sys_id: cleaned, name: name };
        }

        // B) Exact SAP customer code
        var byCode = new GlideRecord(CUST_TABLE);
        byCode.addQuery(CUST_CODE_FIELD, cleaned);
        byCode.setLimit(2);
        byCode.query();
        var codeMatches = [];
        while (byCode.next()) {
            codeMatches.push({ sys_id: byCode.getUniqueValue(), name: byCode.getValue(CUST_NAME_FIELD) });
        }
        if (codeMatches.length === 1) {
            return { status: 'found', sys_id: codeMatches[0].sys_id, name: codeMatches[0].name };
        }

        // C) Customer name: exact, starts with, contains
        var operators = ['=', 'STARTSWITH', 'CONTAINS'];
        for (var i = 0; i < operators.length; i++) {
            var gr = new GlideRecord(CUST_TABLE);
            gr.addQuery(CUST_NAME_FIELD, operators[i], cleaned);
            gr.setLimit(20);
            gr.query();

            var matches = [];
            while (gr.next()) {
                matches.push({
                    sys_id: gr.getUniqueValue(),
                    name: gr.getValue(CUST_NAME_FIELD),
                    code: gr.getValue(CUST_CODE_FIELD),
                    active: gr.getValue('is_active')
                });
            }

            var active = matches.filter(function(m) { return m.active == '1' || m.active == 'true'; });
            if (active.length === 1) return { status: 'found', sys_id: active[0].sys_id, name: active[0].name };
            if (matches.length === 1) return { status: 'found', sys_id: matches[0].sys_id, name: matches[0].name };

            if (matches.length > 1) {
                return {
                    status: 'multiple_matches',
                    message: 'More than one customer matches "' + cleaned + '". Ask the user to type the exact SAP customer code from this list. Do not choose one yourself.',
                    candidates: matches.map(function(m) { return m.name + ' (' + m.code + ')'; })
                };
            }
        }

        return {
            status: 'not_found',
            message: 'No customer found in ' + CUST_TABLE + ' matching "' + cleaned + '".'
        };
    }

    function fail(msg) {
        return JSON.stringify({ status: 'error', message: msg });
    }

})(inputs, _agentic_context_);
